import{KEY,TYPES,SEEDS,fresh,restore,apply,growth,habitat}from'./core.js?v=1';
const $=id=>document.getElementById(id);let state=fresh(),storage=true;try{state=restore(localStorage.getItem(KEY));}catch{storage=false;}let selected=null,mode='look',placing=null,seed='daisy',moving=false,pointer=null;
const outline='stroke="#617355" stroke-width="2" stroke-linejoin="round"';
function art(type,p={}){switch(type){case'bench':return`<ellipse cy="4" rx="48" ry="13" fill="#68795022"/><path d="M-36-12v30M30-12v28M-29-34v26M33-34v26" stroke="#6f7656" stroke-width="7"/><path d="M-44-39l69-15 14 27-71 17z" fill="#b88b62" ${outline}/><path d="M-40-21l72-15 15 15-73 17z" fill="#dcaf7e" ${outline}/><path d="M-37-32l67-14M-34-23l68-14" stroke="#e2be91" stroke-width="3"/>`;
case'bowl':return`<ellipse cy="7" rx="26" ry="11" fill="#65794b22"/><path d="M-24-6Q-23 18 0 18T24-6" fill="#d4b395" ${outline}/><ellipse cy="-6" rx="24" ry="10" fill="${state.water?'#add4cf':'#e9d6b4'}" ${outline}/><path d="M-13-8q10-5 20 0" fill="none" stroke="#fcfff0" stroke-width="2"/>`;
case'pond':return`<path d="M-50-15Q-68 8-25 24T49 13Q77-11 31-30T-50-15" fill="#a3b19a" ${outline}/><path d="M-45-11Q-56 5-23 18T43 9Q65-10 28-23T-45-11" fill="#a5cbc7"/><path d="M-34 3Q-5-8 23 2" fill="none" stroke="#e3efdb" stroke-width="3"/><ellipse cx="30" cy="-9" rx="15" ry="6" fill="#739975"/><path d="M26-9l10-4" stroke="#a4b78a"/>`;
case'path':return`<path d="M-29-5L-8-16 24-10 33 5 6 17-26 9z" fill="#e1d9bb" stroke="#a1ac8a" stroke-width="2"/><path d="M-20-3L-7-9 16-6" fill="none" stroke="#f9f2d8" stroke-width="3"/>`;
case'fence':return`<path d="M-38-30L36-45v10l-74 15zM-38-11L36-26v9L-38-2z" fill="#eadcc0" ${outline}/>${[-30,0,30].map(x=>`<path d="M${x} ${-35-x*.2}v50" stroke="#8e9a77" stroke-width="10"/><path d="M${x-2} ${-35-x*.2}v47" stroke="#e7dfc2" stroke-width="6"/>`).join('')}`;
case'lamp':return`<ellipse cy="5" rx="16" ry="6" fill="#64714c22"/><path d="M0 4v-79" stroke="#6b7b61" stroke-width="7"/><path d="M-17-83L0-97 17-83 12-58H-12z" fill="#f3dfa1" ${outline}/><path d="M-21-82L0-101 21-82z" fill="#6c8067" ${outline}/><path d="M0-79v19" stroke="#bfad70" stroke-width="2"/>`;
case'table':return`<ellipse cy="7" rx="40" ry="12" fill="#52694b22"/><path d="M-23-20v37M24-20v37M0-25v30" stroke="#a28362" stroke-width="6"/><ellipse cy="-26" rx="43" ry="21" fill="#e4c69d" ${outline}/><path d="M-32-27q32-13 63 0" fill="none" stroke="#f5dfb9" stroke-width="3"/><path d="M-4-38v12q12 6 17-1v-12" fill="#fff5dc" ${outline}/><ellipse cx="6" cy="-39" rx="11" ry="5" fill="#bd9570"/><path d="M16-38q14 2 0 10" fill="none" stroke="#647356" stroke-width="2"/>`;
case'cushion':return`<ellipse cy="4" rx="35" ry="13" fill="#64745022"/><path d="M-35-6Q-24-29 8-21T36 2Q24 20-10 14T-35-6" fill="#d9a99a" ${outline}/><path d="M-27-6Q-5-20 25-6" fill="none" stroke="#efc8b8" stroke-width="3"/>`;
case'tree':return`<ellipse cy="7" rx="44" ry="16" fill="#64784b22"/><path d="M-5 5l-3-90h15L9 5" fill="#aa8963" ${outline}/><path d="M0-33l-24-28M1-50l26-25" stroke="#9e805c" stroke-width="8"/><path d="M-48-88Q-70-127-33-144Q-16-178 16-152Q56-164 57-124Q80-99 48-78Q21-51-9-76Q-36-59-48-88" fill="#92ad77" ${outline}/><path d="M-39-126q19-25 44-17M15-119q28-13 34 6" fill="none" stroke="#b8c891" stroke-width="10" stroke-linecap="round"/>${[[-30,-105],[24,-88],[30,-136]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="8" fill="#dba186"/><path d="M${x} ${y-6}v-7" stroke="#617350" stroke-width="2"/>`).join('')}`;
case'pot':{const g=growth(p),grown=g>=1;let leaves='';if(p.seed){const h=20+g*39;leaves=`<path d="M0-19v-${h}" stroke="#6b895a" stroke-width="4"/><path d="M0-32Q-26-53-22-33Q-14-21 0-26M0-40Q24-61 23-40Q12-29 0-34" fill="#8ba36e" stroke="#6b895a" stroke-width="1.5"/>`;if(grown){if(p.seed==='lavender')leaves+=`<path d="M-12-38v-29M12-39v-33" stroke="#73865f" stroke-width="3"/>${[[-12,-71],[0,-83],[12,-76]].map(([x,y])=>[0,8,16].map(d=>`<ellipse cx="${x}" cy="${y+d}" rx="7" ry="6" fill="#afa4c6" stroke="#8c83a3"/>`).join('')).join('')}`;else if(p.seed==='tulip')leaves+='<path d="M-17-82l9 12 8-17 9 17 9-12v20q-17 23-35 0z" fill="#d9a397" stroke="#ad8077" stroke-width="2"/>';else leaves+=`${[0,60,120,180,240,300].map(a=>`<ellipse cx="0" cy="-91" rx="8" ry="14" fill="#fff6d9" stroke="#d3c7a7" transform="rotate(${a} 0 -77)"/>`).join('')}<circle cy="-77" r="10" fill="#d6b96e"/>`;}}return`<ellipse cy="7" rx="25" ry="9" fill="#69784e22"/><path d="M-24-19l6 34Q0 24 18 15l6-34" fill="#c99073" stroke="#9d785f" stroke-width="2"/><ellipse cy="-19" rx="26" ry="11" fill="#ddb194" stroke="#9d785f" stroke-width="2"/><ellipse cy="-20" rx="20" ry="7" fill="#796a51"/>${leaves}`;}
}return'';}
function cat(sleep=false){return`<ellipse cy="9" rx="28" ry="10" fill="#68825822"/><path class="tail" d="M24 1q31-4 13-26" fill="none" stroke="#b8a68c" stroke-width="10" stroke-linecap="round"/><ellipse cy="-5" rx="25" ry="18" fill="#dccbb2" stroke="#827e66" stroke-width="2"/><path d="M-26-21l-4-23 18 10Q0-40 11-31l18-12-4 26Q27 7 0 8T-26-21" fill="#e9ddc5" stroke="#827e66" stroke-width="2"/><path d="M-25-36l9 6-7 5M22-35l-9 6 8 4" fill="#d8aba0"/><path d="M-7-31l3 9M1-33v10M9-31l-3 9" stroke="#b8a68c" stroke-width="3"/><path d="${sleep?'M-16-13q5 5 10 0M7-13q5 5 10 0':'M-12-17v5M12-17v5'}" fill="none" stroke="#5a6452" stroke-width="3" stroke-linecap="round"/><path d="M-3-7l3 3 3-3M0-4q-6 6-9 0M0-4q6 6 9 0" fill="none" stroke="#927b6e" stroke-width="1.5"/>${state.lastPet&&Date.now()-state.lastPet<6000?'<path class="heart" d="M-7-59q-12-13-17-3t17 20q26-15 17-23t-17 6" fill="#d49c94"/>':''}`;}
const point=(c,r)=>[400+(c-r)*43,250+(c+r)*22];
function render(){const h=habitat(state);$('world').className=mode==='decorate'?'editing':'';const items=[...state.items].sort((a,b)=>(a.c+a.r)-(b.c+b.r));const tiles=[];for(let r=0;r<7;r++)for(let c=0;c<7;c++){if(!((c<3)&&(r<2))){const[x,y]=point(c,r);tiles.push(`<path class="tile" data-c="${c}" data-r="${r}" tabindex="0" role="button" aria-label="잔디 ${c+1}열 ${r+1}행" d="M${x} ${y-22}l43 22-43 22-43-22z"/>`);}}
let catAt=point(5,5),sleep=false;if(h.ready){const cozy=state.items.find(p=>p.type==='cushion')||state.items.find(p=>p.type==='bench');if(cozy){catAt=point(cozy.c,cozy.r);catAt[1]-=cozy.type==='bench'?25:0;sleep=true;}}
$('world').innerHTML=`<svg viewBox="0 0 800 640" role="group" aria-label="가구와 식물이 있는 작은 정원"><defs><linearGradient id="grass" x2="0" y2="1"><stop stop-color="#c9dba9"/><stop offset="1" stop-color="#a8c28a"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="12"/></filter></defs><g class="cloud" fill="#fffdf2" opacity=".8"><ellipse cx="160" cy="137" rx="43" ry="13"/><ellipse cx="184" cy="124" rx="26" ry="20"/><ellipse cx="630" cy="177" rx="51" ry="14"/><ellipse cx="610" cy="163" rx="24" ry="20"/></g><ellipse cx="400" cy="480" rx="261" ry="91" fill="#8aa57b33" filter="url(#shadow)"/><path d="M99 382L400 228 701 382v31L400 567 99 413z" fill="#b7ae87"/><path d="M400 536v31l301-154v-31" fill="#a19b76"/><path d="M99 382L400 228 701 382 400 536z" fill="url(#grass)" stroke="#9bae83" stroke-width="2"/>
<g transform="translate(400 249)"><path d="M-124-53L-5-113 105-58 0-1z" fill="#c6bb99"/><path d="M-123-53V-153L0-94V-1z" fill="#ece1c3" stroke="#a3987b" stroke-width="2"/><path d="M0-94l105-58v94L0-1z" fill="#dacdac" stroke="#a3987b" stroke-width="2"/><path d="M-140-154l77-109L13-231 122-151 0-86z" fill="#9bac8c" stroke="#788b70" stroke-width="3"/><path d="M-140-154l77-109L13-231-3-88z" fill="#b0bf9a"/><path d="M-122-169l66-73M-99-160l64-72M-75-147l61-68M-53-137l59-65M24-208l80 61M17-188l61 48" fill="none" stroke="#8fA582" stroke-width="2" opacity=".8"/><path d="M40-223v-58l25-14 23 13v69" fill="#d4c4a5" stroke="#899478" stroke-width="2"/><path d="M-81-69v-68l34 16v68" fill="#8b9b80" stroke="#8c9275" stroke-width="2"/><path d="M-74-78v-46l19 9v47" fill="#b7d0bc"/><circle cx="-53" cy="-76" r="3" fill="#e9cf91"/><path d="M29-83l43-23v37L29-46z" fill="#afc8b7" stroke="#8f977a" stroke-width="3"/><path d="M51-94v37M30-65l40-23" stroke="#eee6cb" stroke-width="4"/><path d="M-87-64l43 21v8l-43-21z" fill="#b0a17f"/><path d="M27-43l47-25v9L27-34z" fill="#b1a382"/></g>
<g fill="#e6ebbe" opacity=".8">${[[170,390],[265,455],[570,435],[440,500],[615,375]].map(([x,y])=>`<path d="M${x} ${y}l-3-9 7 5 4-10 3 13"/>`).join('')}</g>${tiles.join('')}${items.map(p=>{const[x,y]=point(p.c,p.r);return`<g class="object ${selected===p.id?'selected':''}" data-id="${p.id}" transform="translate(${x} ${y})" role="button" tabindex="0" aria-label="${TYPES[p.type].name}${p.seed?' · '+SEEDS[p.seed]:''}"><ellipse class="selection" rx="38" ry="19"/><g transform="scale(${p.rot?-1:1} 1)">${art(p.type,p)}</g><rect x="-35" y="-50" width="70" height="65" fill="transparent"/></g>`;}).join('')}${h.ready?`<g class="object cat" data-cat="1" transform="translate(${catAt.join(' ')})" role="button" tabindex="0" aria-label="고양이 모모 쓰다듬기">${cat(sleep)}</g>`:''}<g transform="translate(184 475)"><path d="M0 0v-65" stroke="#8a8d66" stroke-width="5"/><path d="M-26-78l49 9v27l-49-9z" fill="#e9d7ae" stroke="#a59f7d" stroke-width="2"/><text x="-17" y="-57" font-size="12" fill="#738369">MY PARK</text></g></svg>`;
renderContext();renderShelf();$('look').classList.toggle('active',mode==='look');$('decorate').classList.toggle('active',mode==='decorate');$('plants').classList.toggle('active',mode==='seeds');}
function say(t){$('bubble').textContent=t;}
function dispatch(e){const r=apply(state,e);if(!r.ok){say(r.why);return false;}state=r.state;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storage=false;$('save-status').textContent='이 브라우저에서는 저장이 제한돼요. 창을 닫으면 진행을 잃을 수 있어요.';}render();return true;}
function renderContext(){const p=state.items.find(p=>p.id===selected),h=habitat(state);if(!p){$('context').innerHTML=`<div class="info">${h.ready?'모모가 정원에 놀러 왔어요':'모모를 기다리는 작은 마당'}<small>${h.ready?`친밀도 ${'♥'.repeat(state.hearts)}${'♡'.repeat(10-state.hearts)} · 고양이를 눌러 인사해요`:'꽃 한 송이 + 물이 담긴 그릇을 준비해요'}</small></div>`;return;}let actions='';const g=growth(p);if(p.type==='pot')actions=p.seed?`<button data-act="water">${g>=1?'활짝 핀 꽃':'물 주기'}</button>`:`<button data-act="plant">씨앗 심기</button>`;if(p.type==='bowl')actions='<button data-act="fill">물 채우기</button>';
if(mode==='decorate')actions+='<button class="secondary" data-act="move">옮기기</button><button class="secondary" data-act="rotate">돌리기</button><button class="secondary" data-act="store">보관</button>';
$('context').innerHTML=`<div class="info">${p.seed?SEEDS[p.seed]:TYPES[p.type].name}<small>${moving?'옮길 빈 잔디 칸을 눌러 주세요':p.seed?g>=1?'활짝 피었어요 · 정원에 오래 남아요':`자라는 중 ${Math.floor(g*100)}% · 물을 주면 조금 빨라져요`:mode==='decorate'?'직접 끌거나 옮기기를 눌러 이동해요':'눌러서 돌보고, 꾸미기에서 옮겨요'}</small>${p.seed?`<div class="progress"><i style="width:${g*100}%"></i></div>`:''}</div><div class="actions">${actions}</div>`;}
function renderShelf(){const sh=$('shelf'),scroll=sh.scrollLeft;sh.hidden=mode==='look';if(mode==='decorate'){sh.innerHTML=Object.entries(TYPES).map(([type,t])=>`<button class="item ${placing===type?'active':''}" data-kind="${type}"><svg viewBox="-65 -160 130 190" aria-hidden="true">${art(type)}</svg>${t.name}<small>${t.limit-state.items.filter(p=>p.type===type).length}개 남음</small></button>`).join('');}else if(mode==='seeds'){sh.innerHTML=Object.entries(SEEDS).map(([k,n])=>`<button class="item ${seed===k?'active':''}" data-seed="${k}"><span class="seed">${k==='daisy'?'✿':k==='tulip'?'❀':'❧'}</span>${n}<small>씨앗 무제한</small></button>`).join('');}sh.scrollLeft=scroll;}
function modal(html){$('paper').innerHTML=html;$('dialog').showModal();}
function help(){modal('<small>모모의 작은 정원 · 첫 체험판 0.1</small><h2>조금씩 가꾸는<br>나만의 작은 세계.</h2><p>① 화분을 눌러 씨앗을 심어요.<br>② 물을 주고 꽃이 피기를 기다려요.<br>③ 꾸미기에서 물그릇을 놓고 채워요.</p><p>꽃과 물이 준비되면 모모가 찾아와요. 벤치와 방석에서는 편히 쉬어요.</p><small>체험판에서는 약 2분이면 꽃이 피어요. 물 주기로 기다림을 줄일 수 있어요. 접속하지 않아도 자라고, 시들거나 죽지 않아요. 모든 가구는 무료예요.</small><button class="primary" data-act="start">내 정원 둘러보기</button>');}
$('close').onclick=()=>$('dialog').close();$('help').onclick=help;$('look').onclick=()=>{mode='look';moving=false;placing=null;render();say('화분이나 물건을 눌러 살펴보세요.');};$('decorate').onclick=()=>{mode='decorate';render();say('아래 물건을 고르고 빈 잔디 칸에 놓아 주세요.');};$('plants').onclick=()=>{mode='seeds';moving=false;placing=null;render();say('씨앗을 고른 다음 빈 화분을 눌러 심어요.');};
$('album').onclick=()=>modal(`<small>GARDEN JOURNAL</small><h2>우리 정원의 기록</h2>${Object.entries(SEEDS).map(([k,n])=>{const ps=state.items.filter(p=>p.seed===k);return`<div class="journal"><b>${n}</b><p>${ps.length?`${ps.filter(p=>growth(p)>=1).length}송이 개화 · ${ps.filter(p=>growth(p)<1).length}개 성장 중`:'아직 심지 않았어요'}</p></div>`;}).join('')}<p>모모와의 친밀도 ${state.hearts} / 10</p><small>현재 정원에 놓인 식물의 기록이에요. 가구와 식물은 이 기기에 자동 저장돼요. 친구 방문·온라인 계정은 아직 없는 첫 체험판이에요.</small>`);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.kind){placing=b.dataset.kind;selected=null;moving=false;renderShelf();renderContext();say(`${TYPES[placing].name} · 놓을 빈 잔디 칸을 눌러 주세요.`);}if(b.dataset.seed){seed=b.dataset.seed;renderShelf();say(`${SEEDS[seed]} 씨앗을 골랐어요. 빈 화분을 눌러 주세요.`);}const a=b.dataset.act;if(a==='start'){$('dialog').close();dispatch({type:'welcome'});}if(a==='plant'){mode='seeds';render();if(dispatch({type:'plant',id:selected,seed}))say(`${SEEDS[seed]} 씨앗을 심었어요. 물을 주면 더 빨리 자라요.`);}if(a==='water'){if(dispatch({type:'water',id:selected}))say(growth(state.items.find(p=>p.id===selected))>=1?'첫 꽃이 활짝 피었어요! 물그릇도 준비해 볼까요?':'촉촉하게 물을 주었어요. 조금 더 자랐네요.');}if(a==='fill'&&dispatch({type:'fill',id:selected}))say(habitat(state).ready?'꽃 향기를 따라 모모가 찾아왔어요!':'깨끗한 물을 채웠어요. 꽃이 피면 모모가 찾아올 거예요.');if(a==='move'){moving=true;placing=null;renderContext();say('옮길 빈 잔디 칸을 누르거나 물건을 끌어 주세요.');}if(a==='rotate')dispatch({type:'rotate',id:selected});if(a==='store'){if(dispatch({type:'store',id:selected})){selected=null;render();say('주머니에 보관했어요. 꾸미기에서 다시 놓을 수 있어요.');}}});
function pick(target){if(target.closest('[data-cat]')){if(dispatch({type:'pet'}))say('가르릉… 모모가 눈을 가늘게 뜨고 인사해요. ♥');return;}const obj=target.closest('[data-id]');if(obj){selected=Number(obj.dataset.id);placing=null;moving=false;const p=state.items.find(p=>p.id===selected);if(mode==='seeds'&&p.type==='pot'&&!p.seed){if(dispatch({type:'plant',id:selected,seed}))say(`${SEEDS[seed]} 씨앗을 심었어요. 물을 주어 볼까요?`);}else render();return;}const t=target.closest('[data-c]');if(t){const c=Number(t.dataset.c),r=Number(t.dataset.r);if(moving&&selected){if(dispatch({type:'move',id:selected,c,r})){moving=false;render();say('새 자리에 놓았어요.');}}else if(placing){if(dispatch({type:'place',kind:placing,c,r})){selected=state.next-1;renderContext();say(`${TYPES[placing].name}을 놓았어요.`);}}else say('꾸미기에서 물건을 골라 나만의 마당을 만들어 보세요.');}}
$('world').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,id:Number(e.target.closest('[data-id]')?.dataset.id),moved:false};});$('world').addEventListener('pointermove',e=>{if(pointer&&Math.hypot(pointer.x-e.clientX,pointer.y-e.clientY)>12)pointer.moved=true;});$('world').addEventListener('pointerup',e=>{const p=pointer;pointer=null;if(p?.moved&&p.id&&mode==='decorate'){const svg=$('world').querySelector('svg'),b=svg.getBoundingClientRect(),x=(e.clientX-b.left)*800/b.width,y=(e.clientY-b.top)*640/b.height;const c=Math.round(((x-400)/43+(y-250)/22)/2),r=Math.round(((y-250)/22-(x-400)/43)/2);selected=p.id;if(dispatch({type:'move',id:p.id,c,r}))say('새 자리에 놓았어요.');return;}if(!p?.moved)pick(e.target);});$('world').addEventListener('pointercancel',()=>pointer=null);$('world').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(e.target);}});
let lastTick='';setInterval(()=>{if(pointer||$('dialog').open)return;const signature=state.items.filter(p=>p.seed).map(p=>Math.floor(growth(p)*100)).join()+':'+(Date.now()-state.lastPet<6000);if(signature!==lastTick){lastTick=signature;render();}},2000);render();if(!storage)$('save-status').textContent='이 브라우저에서는 저장이 제한돼요.';if(!state.welcomed)help();
